from abc import ABC, abstractmethod
from uuid import UUID

class GameRepository(ABC):
    @abstractmethod
    def get(self, uuid: UUID) -> Game: ...

    @abstractmethod
    def save(self, game: Game) -> None: ...

    @abstractmethod
    def list_waiting(self, exclude_player_uuid: UUID | None = None) -> list[Game]: ...

class InMemoryGameRepository(GameRepository):
    def __init__(self):
        self._games: dict[UUID, Game] = {}

    def get(self, uuid: UUID) -> Game:
        if uuid not in self._games:
            raise GameNotFoundError(f"Game {uuid} not found")
        return self._games[uuid]

    def save(self, game: Game) -> None:
        self._games[game.uuid] = game

    def list_waiting(self, exclude_player_uuid=None) -> list[Game]:
        return [g for g in self._games.values()
                if g.status == GameStatus.WAITING and g.player1_uuid != exclude_player_uuid]

